<!doctype html>
<html lang="en" data-resolution="landscape">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=1920, height=1080" />
    <title>Tag - Bug Found</title>
    <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
    <style>
      * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
      }
      html,
      body {
        margin: 0;
        width: 1920px;
        height: 1080px;
        overflow: hidden;
        background: transparent;
      }
      body {
        font-family: -apple-system, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
      }

      #root {
        position: relative;
        width: 1920px;
        height: 1080px;
        background: transparent;
      }

      #overlay-wrap {
        position: absolute;
        inset: 0;
      }

      /* --- shared liquid-glass tag component --- */
      .tag-wrap {
        position: absolute;
        left: 90px;
        top: 856px;
      }

      .tag {
        position: relative;
        display: inline-flex;
        align-items: center;
        gap: 18px;
        padding: 20px 38px 20px 20px;
        border-radius: 48px;
        background: linear-gradient(
          135deg,
          rgba(255, 255, 255, 0.18) 0%,
          rgba(255, 255, 255, 0.06) 100%
        );
        -webkit-backdrop-filter: blur(22px) saturate(150%);
        backdrop-filter: blur(22px) saturate(150%);
        box-shadow:
          0 18px 50px rgba(0, 0, 0, 0.4),
          inset 0 1px 0 rgba(255, 255, 255, 0.45),
          inset 0 -1px 0 rgba(255, 255, 255, 0.05);
        overflow: hidden;
      }

      /* gradient border ring that catches light at an angle */
      .tag::before {
        content: "";
        position: absolute;
        inset: 0;
        border-radius: inherit;
        padding: 1.5px;
        background: linear-gradient(
          135deg,
          rgba(255, 255, 255, 0.7) 0%,
          rgba(255, 255, 255, 0.1) 30%,
          rgba(255, 255, 255, 0) 55%,
          rgba(255, 255, 255, 0.25) 100%
        );
        -webkit-mask:
          linear-gradient(#fff 0 0) content-box,
          linear-gradient(#fff 0 0);
        -webkit-mask-composite: xor;
        mask-composite: exclude;
        pointer-events: none;
      }

      /* one-shot diagonal sheen sweep on entrance */
      .tag .sheen {
        position: absolute;
        top: -80%;
        left: -140%;
        width: 55%;
        height: 260%;
        background: linear-gradient(
          120deg,
          rgba(255, 255, 255, 0.3) 0%,
          rgba(255, 255, 255, 0) 60%
        );
        transform: rotate(-16deg);
        pointer-events: none;
      }

      .tag-icon {
        position: relative;
        z-index: 1;
        flex: none;
        width: 52px;
        height: 52px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        background: linear-gradient(120deg, #ff6a5c 0%, #ffb37a 50%, #e0333f 100%);
        box-shadow: 0 0 22px 2px rgba(207, 63, 196, 0.45);
      }

      .tag-icon svg {
        width: 26px;
        height: 26px;
        fill: #fff;
      }

      .tag-label {
        position: relative;
        z-index: 1;
        font-size: 32px;
        font-weight: 800;
        letter-spacing: 2px;
        text-transform: uppercase;
        color: #ffffff;
        white-space: nowrap;
        text-shadow: 0 2px 12px rgba(0, 0, 0, 0.35);
      }
    </style>
  </head>
  <body>
    <div
      id="root"
      data-composition-id="main"
      data-start="0"
      data-duration="2.1"
      data-width="1920"
      data-height="1080"
      data-fps="60"
    >
      <div id="overlay-wrap" class="clip" data-start="0" data-duration="2.1" data-track-index="1">
        <div class="tag-wrap" id="tag-wrap">
          <div class="tag" id="tag">
            <div class="sheen" id="sheen" data-layout-allow-overflow></div>
            <div class="tag-icon" id="tag-icon">
              <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M12 2.5 23 21H1L12 2.5zm0 6.2a1.1 1.1 0 0 0-1.1 1.1v4.4a1.1 1.1 0 0 0 2.2 0v-4.4A1.1 1.1 0 0 0 12 8.7zm0 8.4a1.3 1.3 0 1 0 0 2.6 1.3 1.3 0 0 0 0-2.6z"/></svg>
            </div>
            <div class="tag-label" id="tag-label">BUG FOUND</div>
          </div>
        </div>
      </div>
    </div>

    <script>
      window.__timelines = window.__timelines || {};
      const tl = gsap.timeline({ paused: true });

      // --- Entrance: panel lands, then icon, then label (staggered, never simultaneous) ---
      tl.fromTo(
        "#tag",
        { opacity: 0, x: -28, scale: 0.88 },
        { opacity: 1, x: 0, scale: 1, duration: 0.45, ease: "power3.out" },
        0,
      );
      tl.fromTo(
        "#sheen",
        { x: "0%" },
        { x: "260%", duration: 0.55, ease: "power2.out" },
        0.05,
      );
      tl.fromTo(
        "#tag-icon",
        { opacity: 0, scale: 0.4 },
        { opacity: 1, scale: 1, duration: 0.35, ease: "back.out(1.7)" },
        0.18,
      );
      tl.fromTo(
        "#tag-label",
        { opacity: 0, x: 14 },
        { opacity: 1, x: 0, duration: 0.35, ease: "power2.out" },
        0.3,
      );


      // --- Exit ---
      tl.to(
        "#tag-wrap",
        { opacity: 0, y: -14, scale: 0.95, duration: 0.4, ease: "power2.in" },
        1.60,
      );

      window.__timelines["main"] = tl;
    </script>
  </body>
</html>

