126	    <script>
127	      (function () {
128	        window.__timelines = window.__timelines || {};
129	
130	        var SVG_NS = "http://www.w3.org/2000/svg";
131	        var W = 820; // traced rectangle width
132	        var H = 210; // traced rectangle height
133	        var DUR = 4.8;
134	
135	        var vars =
136	          window.__hyperframes && window.__hyperframes.getVariables
137	            ? window.__hyperframes.getVariables()
138	            : {};
139	
140	        function num(v, fallback) {
141	          var n = typeof v === "number" ? v : parseFloat(v);
142	          return isFinite(n) ? n : fallback;
143	        }
144	
145	        var accent = /^#[0-9a-fA-F]{6}$/.test(String(vars.accent))
146	          ? String(vars.accent)
147	          : "#cc9149";
148	        var mode = vars.movement === "glide" ? "glide" : "step";
149	        var speed = Math.max(0.05, num(vars.speed, 1.6)); // corners per second
150	        var radius = Math.min(Math.min(W, H) / 2, Math.max(0, num(vars.cornerRadius, 26)));
151	        var thickness = Math.max(0.5, num(vars.thickness, 5));
152	        var arcFrac = Math.min(1, Math.max(0.02, num(vars.arcLength, 22) / 100));
153	        var glow = Math.max(0, num(vars.glow, 1));
154	
155	        // Hot core: the accent lifted most of the way to white, the way a real
156	        // filament reads brighter than its halo.
157	        function towardWhite(hex, amount) {
158	          var v = parseInt(hex.slice(1), 16);
159	          var out = "#";
160	          for (var s = 16; s >= 0; s -= 8) {
161	            var c = (v >> s) & 255;
162	            var m = Math.round(c + (255 - c) * amount);
163	            out += (m < 16 ? "0" : "") + m.toString(16);
164	          }
165	          return out;
166	        }
167	        var hot = towardWhite(accent, 0.78);
168	
169	        // ---- geometry -------------------------------------------------------
170	        // Rounded rect, clockwise, starting where the top edge leaves the
171	        // top-left corner arc.
172	        var r = radius;
173	        var arc = "A " + r + " " + r + " 0 0 1 ";
174	        var d = [
175	          "M " + r + " 0",
176	          "H " + (W - r),
177	          arc + W + " " + r,
178	          "V " + (H - r),
179	          arc + (W - r) + " " + H,
180	          "H " + r,
181	          arc + "0 " + (H - r),
182	          "V " + r,
183	          arc + r + " 0",
184	          "Z",
185	        ].join(" ");
186	
187	        var fillEl = document.getElementById("nb-fill");
188	        var railEl = document.getElementById("nb-rail");
189	        fillEl.setAttribute("d", d);
190	        railEl.setAttribute("d", d);
191	        railEl.setAttribute("stroke", accent);
192	        railEl.setAttribute("stroke-width", String(thickness));
193	        railEl.setAttribute("stroke-opacity", "0.14");
194	
195	        // Analytic perimeter, then rescaled to whatever length the renderer
196	        // actually measures for the path so dash distances line up exactly.
197	        var SW = W - 2 * r; // straight run, horizontal
198	        var SH = H - 2 * r; // straight run, vertical
199	        var AC = (Math.PI * r) / 2; // one corner arc
200	        var P_ANALYTIC = 2 * SW + 2 * SH + 4 * AC;
201	        var P = railEl.getTotalLength() || P_ANALYTIC;
202	        var K = P / P_ANALYTIC;
203	
204	        // Distance along the path of the MIDPOINT of each corner arc, so the
205	        // light parks centred on the corner rather than skidding past it.
206	        var CORNERS = [
207	          (SW + AC / 2) * K, // top-right
208	          (SW + SH + 1.5 * AC) * K, // bottom-right
209	          (2 * SW + SH + 2.5 * AC) * K, // bottom-left
210	          (2 * SW + 2 * SH + 3.5 * AC) * K, // top-left
211	        ];
212	
213	        /** Absolute path distance of corner k, for any integer k (k may be
214	         * negative or beyond one lap). Pure function of k — no accumulator. */
215	        function cornerPos(k) {
216	          var lap = Math.floor(k / 4);
217	          var i = k - lap * 4;
218	          return CORNERS[i] + lap * P;
219	        }
220	
221	        // ---- easing ---------------------------------------------------------
222	        // The step curve overshoots (y2 = 1.05); that overshoot IS the snap.
223	        function cubicBezier(x1, y1, x2, y2) {
224	          function axis(t, a, b) {
225	            var u = 1 - t;
226	            return 3 * u * u * t * a + 3 * u * t * t * b + t * t * t;
227	          }
228	          return function (x) {
229	            if (x <= 0) return 0;
230	            if (x >= 1) return 1;
231	            var lo = 0;
232	            var hi = 1;
233	            var t = x;
234	            // Fixed iteration count: same input, same output, every run.
235	            for (var i = 0; i < 32; i++) {
236	              t = (lo + hi) / 2;
237	              if (axis(t, x1, x2) < x) lo = t;
238	              else hi = t;
239	            }
240	            return axis(t, y1, y2);
241	          };
242	        }
243	        var ease =
244	          mode === "glide" ? cubicBezier(0.65, 0, 0.35, 1) : cubicBezier(0.72, 0.16, 0.18, 1.05);
245	
246	        var beat = 1 / speed; // seconds per corner hop
247	
248	        /** Head position (path distance) at time t. floor/frac of t/beat is the
249	         * closed form of the reference's `stepT += dt` accumulator. */
250	        function headAt(t) {
251	          var total = t / beat;
252	          var k = Math.floor(total);
253	          var u = total - k;
254	          var a = cornerPos(k);
255	          var b = cornerPos(k + 1);
256	          return a + (b - a) * ease(u);
257	        }
258	
259	        // ---- arc construction ----------------------------------------------
260	        // Each arc is a run of abutting dash segments whose opacity falls off
261	        // behind the head; that ramp is the taper. Geometry lives once in
262	        // <defs> and is shared by every bloom layer through <use>.
263	        function buildSegments(groupId, count, falloff) {
264	          var g = document.getElementById(groupId);
265	          var segs = [];
266	          for (var i = 0; i < count; i++) {
267	            var p = document.createElementNS(SVG_NS, "path");
268	            p.setAttribute("d", d);
269	            p.setAttribute("fill", "none");
270	            p.setAttribute("stroke-linecap", i === 0 ? "round" : "butt");
271	            p.setAttribute("opacity", String(Math.pow(1 - i / count, falloff)));
272	            g.appendChild(p);
273	            segs.push(p);
274	          }
275	          return segs;
276	        }
277	
278	        var GLOW_SEGS = 20;
279	        var CORE_SEGS = 26;
280	        var glowLen = arcFrac * P;
281	        var coreLen = 0.34 * glowLen;
282	
283	        var arcs = [
284	          {
285	            offset: 0,
286	            glow: buildSegments("nb-seg-a-glow", GLOW_SEGS, 2.6),
287	            core: buildSegments("nb-seg-a-core", CORE_SEGS, 1.4),
288	          },
289	          {
290	            // Half a lap behind: the diametrically opposite corner. The pairing
291	            // is most of why the effect reads as designed rather than random.
292	            offset: 2,
293	            glow: buildSegments("nb-seg-b-glow", GLOW_SEGS, 2.6),
294	            core: buildSegments("nb-seg-b-core", CORE_SEGS, 1.4),
295	          },
296	        ];
297	
298	        // Three stacked bloom layers (soft / medium / wide) plus the filament.
299	        // `spread` widens the stroke before it is blurred — that pairing, not
300	        // the blur alone, is what makes the halo read as emitted light.
301	        var MAX_REACH = 36;
302	        var LAYERS = [
303	          { blur: 30, spread: 1, opacity: 0.18, stroke: accent, deep: true },
304	          { blur: 15, spread: 0.6, opacity: 0.3, stroke: accent, deep: true },
305	          { blur: 8, spread: 0.3, opacity: 0.5, stroke: accent, deep: true },
306	          { blur: 4, spread: 0.05, opacity: 0.9, stroke: hot, core: true },
307	          { blur: 0, spread: -0.012, opacity: 1, stroke: "#ffffff", core: true },
308	        ];
309	
310	        var under = document.getElementById("nb-bloom-under");
311	        var over = document.getElementById("nb-bloom-over");
312	        ["a", "b"].forEach(function (tag) {
313	          LAYERS.forEach(function (layer) {
314	            var u = document.createElementNS(SVG_NS, "use");
315	            u.setAttribute("href", "#nb-seg-" + tag + "-" + (layer.core ? "core" : "glow"));
316	            u.setAttribute("stroke", layer.stroke);
317	            u.setAttribute(
318	              "stroke-width",
319	              String(Math.max(0.5, thickness + 2 * layer.spread * MAX_REACH * glow)),
320	            );
321	            u.setAttribute("opacity", String(Math.min(1, layer.opacity * glow)));
322	            if (layer.blur > 0) u.style.filter = "blur(" + layer.blur + "px)";
323	            (layer.deep ? under : over).appendChild(u);
324	          });
325	        });
326	
327	        /** Lay a segment run out behind `head`. Every value derives from head. */
328	        function layout(segs, head, length) {
329	          var step = length / segs.length;
330	          for (var i = 0; i < segs.length; i++) {
331	            var start = head - (i + 1) * step;
332	            start = ((start % P) + P) % P;
333	            segs[i].setAttribute("stroke-dasharray", step + " " + (P - step));
334	            segs[i].setAttribute("stroke-dashoffset", String(-start));
335	          }
336	        }
337	
338	        function render(t) {
339	          for (var i = 0; i < arcs.length; i++) {
340	            var head = headAt(t + arcs[i].offset * beat);
341	            layout(arcs[i].glow, head, glowLen);
342	            layout(arcs[i].core, head, coreLen);
343	          }
344	        }
345	
346	        // ---- timeline -------------------------------------------------------
347	        var wrap = document.getElementById("nb-wrap");
348	        var panel = document.getElementById("nb-panel");
349	        var nameEl = document.getElementById("nb-name");
350	        var roleEl = document.getElementById("nb-role");
351	
352	        var tl = gsap.timeline({ paused: true });
353	
354	        gsap.set(wrap, { opacity: 0, scale: 0.965, transformOrigin: "0% 100%" });
355	        gsap.set(nameEl, { y: 18, opacity: 0 });
356	        gsap.set(roleEl, { y: 12, opacity: 0 });
357	
358	        // The driver: linear, spans the whole clip, and every arc position is
359	        // recomputed from its own time value. Seeking to frame N gives the same
360	        // state as playing to frame N because nothing carries over.
361	        var driver = { t: 0 };
362	        tl.to(
363	          driver,
364	          {
365	            t: DUR,
366	            duration: DUR,
367	            ease: "none",
368	            onUpdate: function () {
369	              render(driver.t);
370	            },
371	          },
372	          0,
373	        );
374	
375	        tl.to(wrap, { opacity: 1, scale: 1, duration: 0.55, ease: "power3.out" }, 0.08);
376	        tl.to(nameEl, { y: 0, opacity: 1, duration: 0.5, ease: "power3.out" }, 0.3);
377	        tl.to(roleEl, { y: 0, opacity: 1, duration: 0.5, ease: "power3.out" }, 0.44);
378	
