609	      (function () {
610	        window.__timelines = window.__timelines || {};
611	
612	        var SVG_NS = "http://www.w3.org/2000/svg";
613	        var W = 820; // traced rectangle width
614	        var H = 210; // traced rectangle height
615	        var DUR = 4.8;
616	
617	        var vars =
618	          window.__hyperframes && window.__hyperframes.getVariables
619	            ? window.__hyperframes.getVariables()
620	            : {};
621	
622	        function num(v, fallback) {
623	          var n = typeof v === "number" ? v : parseFloat(v);
624	          return isFinite(n) ? n : fallback;
625	        }
626	
627	        var accent = /^#[0-9a-fA-F]{6}$/.test(String(vars.accent))
628	          ? String(vars.accent)
629	          : "#cc9149";
630	        var mode = vars.movement === "glide" ? "glide" : "step";
631	        var speed = Math.max(0.05, num(vars.speed, 1.6)); // corners per second
632	        var radius = Math.min(Math.min(W, H) / 2, Math.max(0, num(vars.cornerRadius, 26)));
633	        var thickness = Math.max(0.5, num(vars.thickness, 5));
634	        var arcFrac = Math.min(1, Math.max(0.02, num(vars.arcLength, 22) / 100));
635	        var glow = Math.max(0, num(vars.glow, 1));
636	
637	        // Hot core: the accent lifted most of the way to white, the way a real
638	        // filament reads brighter than its halo.
639	        function towardWhite(hex, amount) {
640	          var v = parseInt(hex.slice(1), 16);
641	          var out = "#";
642	          for (var s = 16; s >= 0; s -= 8) {
643	            var c = (v >> s) & 255;
644	            var m = Math.round(c + (255 - c) * amount);
645	            out += (m < 16 ? "0" : "") + m.toString(16);
646	          }
647	          return out;
648	        }
649	        var hot = towardWhite(accent, 0.78);
650	
651	        // ---- geometry -------------------------------------------------------
652	        // Rounded rect, clockwise, starting where the top edge leaves the
653	        // top-left corner arc.
654	        var r = radius;
655	        var arc = "A " + r + " " + r + " 0 0 1 ";
656	        var d = [
657	          "M " + r + " 0",
658	          "H " + (W - r),
659	          arc + W + " " + r,
660	          "V " + (H - r),
661	          arc + (W - r) + " " + H,
662	          "H " + r,
663	          arc + "0 " + (H - r),
664	          "V " + r,
665	          arc + r + " 0",
666	          "Z",
667	        ].join(" ");
