669	        var fillEl = document.getElementById("nb-fill");
670	        var railEl = document.getElementById("nb-rail");
671	        fillEl.setAttribute("d", d);
672	        railEl.setAttribute("d", d);
673	        railEl.setAttribute("stroke", accent);
674	        railEl.setAttribute("stroke-width", String(thickness));
675	        railEl.setAttribute("stroke-opacity", "0.14");
