677	        // Analytic perimeter, then rescaled to whatever length the renderer
678	        // actually measures for the path so dash distances line up exactly.
679	        var SW = W - 2 * r; // straight run, horizontal
680	        var SH = H - 2 * r; // straight run, vertical
681	        var AC = (Math.PI * r) / 2; // one corner arc
682	        var P_ANALYTIC = 2 * SW + 2 * SH + 4 * AC;
683	        var P = railEl.getTotalLength() || P_ANALYTIC;
684	        var K = P / P_ANALYTIC;
