686	        // Distance along the path of the MIDPOINT of each corner arc, so the
687	        // light parks centred on the corner rather than skidding past it.
688	        var CORNERS = [
689	          (SW + AC / 2) * K, // top-right
690	          (SW + SH + 1.5 * AC) * K, // bottom-right
691	          (2 * SW + SH + 2.5 * AC) * K, // bottom-left
692	          (2 * SW + 2 * SH + 3.5 * AC) * K, // top-left
693	        ];
