708	            return 3 * u * u * t * a + 3 * u * t * t * b + t * t * t;
709	          }
710	          return function (x) {
711	            if (x <= 0) return 0;
712	            if (x >= 1) return 1;
713	            var lo = 0;
714	            var hi = 1;
715	            var t = x;
716	            // Fixed iteration count: same input, same output, every run.
717	            for (var i = 0; i < 32; i++) {
718	              t = (lo + hi) / 2;
719	              if (axis(t, x1, x2) < x) lo = t;
720	              else hi = t;
721	            }
722	            return axis(t, y1, y2);
