743	        // behind the head; that ramp is the taper. Geometry lives once in
744	        // <defs> and is shared by every bloom layer through <use>.
745	        function buildSegments(groupId, count, falloff) {
746	          var g = document.getElementById(groupId);
747	          var segs = [];
748	          for (var i = 0; i < count; i++) {
749	            var p = document.createElementNS(SVG_NS, "path");
750	            p.setAttribute("d", d);
