773	            // is most of why the effect reads as designed rather than random.
774	            offset: 2,
775	            glow: buildSegments("nb-seg-b-glow", GLOW_SEGS, 2.6),
776	            core: buildSegments("nb-seg-b-core", CORE_SEGS, 1.4),
777	          },
778	        ];
779	
780	        // Three stacked bloom layers (soft / medium / wide) plus the filament.
781	        // `spread` widens the stroke before it is blurred — that pairing, not
782	        // the blur alone, is what makes the halo read as emitted light.
783	        var MAX_REACH = 36;
