786	          { blur: 15, spread: 0.6, opacity: 0.3, stroke: accent, deep: true },
787	          { blur: 8, spread: 0.3, opacity: 0.5, stroke: accent, deep: true },
788	          { blur: 4, spread: 0.05, opacity: 0.9, stroke: hot, core: true },
789	          { blur: 0, spread: -0.012, opacity: 1, stroke: "#ffffff", core: true },
790	        ];
