792	        var under = document.getElementById("nb-bloom-under");
793	        var over = document.getElementById("nb-bloom-over");
794	        ["a", "b"].forEach(function (tag) {
795	          LAYERS.forEach(function (layer) {
796	            var u = document.createElementNS(SVG_NS, "use");
797	            u.setAttribute("href", "#nb-seg-" + tag + "-" + (layer.core ? "core" : "glow"));
798	            u.setAttribute("stroke", layer.stroke);
799	            u.setAttribute(
800	              "stroke-width",
801	              String(Math.max(0.5, thickness + 2 * layer.spread * MAX_REACH * glow)),
802	            );
803	            u.setAttribute("opacity", String(Math.min(1, layer.opacity * glow)));
804	            if (layer.blur > 0) u.style.filter = "blur(" + layer.blur + "px)";
805	            (layer.deep ? under : over).appendChild(u);
806	          });
807	        });
