809	        /** Lay a segment run out behind `head`. Every value derives from head. */
810	        function layout(segs, head, length) {
811	          var step = length / segs.length;
812	          for (var i = 0; i < segs.length; i++) {
813	            var start = head - (i + 1) * step;
814	            start = ((start % P) + P) % P;
