var headA = document.getElementById("nb-head-a");
var headB = document.getElementById("nb-head-b");
headA.style.filter = "blur(3px)";
headB.style.filter = "blur(3px)";
headA.setAttribute("opacity", "0.95");
headB.setAttribute("opacity", "0.95");
var headEls = [headA, headB];

// Real (x,y) position of each comet head, recomputed every frame from
// t alone. This is the element the check gate's motion sweep keys
// off (a moving bbox), and it doubles as the brightest point of each
// comet — the "hot spot" the light appears to emit from.
function render(t) {
  for (var i = 0; i < comets.length; i++) {
    var head = headAt(t + comets[i].offset);
    layout(comets[i].glow, head, glowLen);
    var pt = railEl.getPointAtLength(head);
    headEls[i].setAttribute("cx", String(pt.x));
    headEls[i].setAttribute("cy", String(pt.y));
  }
}

