var railEl = document.getElementById("nb-rail");
railEl.setAttribute("d", d);

// ---- interior exclusion clip: outer bounding box minus the PIP's
// own rounded-rect footprint (576x432, r=28), positioned at the same
// 16px inset from the traced rail used everywhere else. Evenodd
// fill-rule turns "outer minus inner" into a single clip region that
// covers everything except the PIP box. -----------------------------
var PIP_X = 110 + 16; // 126 — absolute SVG coords (BLOOM_PAD + margin)
var PIP_Y = 110 + 16;
var PIP_W = 576;
var PIP_H = 432;
var PIP_R = 28;
function roundedRectPath(x, y, w, h, r) {
  var a = "A " + r + " " + r + " 0 0 1 ";
  return [
    "M " + (x + r) + " " + y,
    "H " + (x + w - r),
    a + (x + w) + " " + (y + r),
    "V " + (y + h - r),
    a + (x + w - r) + " " + (y + h),
    "H " + (x + r),
    a + x + " " + (y + h - r),
    "V " + (y + r),
    a + (x + r) + " " + y,
    "Z",
  ].join(" ");
}
var outerD = "M -2000 -2000 H 2828 V 2684 H -2000 Z";
var innerD = roundedRectPath(PIP_X, PIP_Y, PIP_W, PIP_H, PIP_R);
document.getElementById("nb-exclude-path").setAttribute("d", outerD + " " + innerD);

var P = railEl.getTotalLength();

